// Extraer posts del body y preparar prompt para clasificación
const body = $input.first().json.body;
const posts = body.posts || [];

if (!posts.length) {
  return [{ json: { error: 'No posts received', classified: [] } }];
}

// Construir prompt con los posts para clasificación batch
const postsSummary = posts.map((p, i) => {
  const caption = (p.caption || '').substring(0, 300);
  return `[${i}] id=${p.id} | type=${p.media_type} | caption="${caption}" | permalink=${p.permalink}`;
}).join('\n');

const prompt = `Eres un clasificador de publicaciones de Instagram para una plataforma de e-commerce y servicios chilena.

Clasifica cada publicación en una de estas categorías:
- "product": Producto físico a la venta (ropa, comida, hamburguesas, tortas, joyas, collares, tecnología, inmuebles, casas, departamentos, autos, muebles, mascotas, artesanía, etc.)
- "service": Servicio ofrecido (barbería, peluquería, limpieza, consulta médica, clase, tutoría, reparación, masaje, manicure, entrenamiento, fotografía, diseño, etc.)
- "ad": Publicidad genérica, promoción sin producto/servicio específico, spam
- "personal": Contenido personal, selfie, evento social, viaje
- "catalog": Catálogo o collage de múltiples productos/servicios en una sola imagen
- "other": Meme, repost, contenido no clasificable

REGLAS IMPORTANTES:
- Si la publicación muestra algo que se puede comprar/adquirir físicamente → "product"
- Si la publicación ofrece algo que se realiza/ejecuta para el cliente → "service"
- Comida preparada (hamburguesas, tortas, sushi) → "product"
- Inmuebles (casas, departamentos, terrenos) → "product" con category "Inmobiliaria"
- Si no puedes determinar el precio, pon price: null (el usuario lo ingresará después)

Para "product", extrae:
- name: nombre corto del producto
- price: precio en CLP si se menciona (solo número, null si no hay)
- description: descripción breve del producto
- brand: marca si se menciona (null si no)
- category: (Ropa, Electrónica, Alimentos, Belleza, Hogar, Inmobiliaria, Joyería, Mascotas, Deportes, Salud, Vehículos, Otro)

Para "service", extrae:
- name: nombre del servicio
- price: precio en CLP si se menciona (solo número, null si no hay)
- description: descripción breve del servicio
- duration_minutes: duración estimada en minutos (barbería=45, manicure=60, consulta=30, clase=60, masaje=60, corte de pelo=30, null si no puedes estimar)
- category: (Belleza, Salud, Educación, Hogar, Deportes, Tecnología, Profesional, Otro)

Publicaciones a clasificar:
${postsSummary}

Responde SOLO con un JSON array. Cada elemento:
{"index": N, "classification": "...", "confidence": 0.0-1.0, "product_data": {"name": "...", "price": null|number, "description": "...", "brand": null|"...", "category": "...", "duration_minutes": null|number}|null}

Incluye product_data para classification="product" y classification="service". Para "service" omite brand. Responde SOLO el JSON array, sin markdown ni explicaciones.`;

return [{ json: { prompt, posts, userId: body.userId } }];

