// Parsear respuesta de OpenAI y enriquecer con datos originales
const posts = $('Preparar Prompt').first().json.posts;
const userId = $('Preparar Prompt').first().json.userId;

let rawContent = '';
try {
  rawContent = $input.first().json.choices[0].message.content;
  // Limpiar posibles backticks de markdown
  rawContent = rawContent.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
} catch (e) {
  return [{ json: { error: 'Failed to parse OpenAI response', classified: [] } }];
}

let classifications = [];
try {
  classifications = JSON.parse(rawContent);
} catch (e) {
  return [{ json: { error: 'Invalid JSON from OpenAI', raw: rawContent, classified: [] } }];
}

// Merge classification con datos originales del post
const classified = classifications.map(c => {
  const post = posts[c.index];
  if (!post) return null;
  return {
    ig_post_id: post.id,
    media_url: post.media_url || post.thumbnail_url,
    thumbnail_url: post.thumbnail_url || post.media_url,
    permalink: post.permalink,
    caption: (post.caption || '').substring(0, 500),
    media_type: post.media_type,
    timestamp: post.timestamp,
    classification: c.classification,
    confidence: c.confidence,
    product_data: c.product_data || null
  };
}).filter(Boolean);

return [{ json: { classified, total: posts.length, products: classified.filter(c => c.classification === 'product').length, services: classified.filter(c => c.classification === 'service').length } }];
